// Извлекаем http(s)-ссылки из text/caption; сообщения без ссылок пропускаем (пустой массив).
// Дедупликация — по $getWorkflowStaticData('global').seen_urls (память без внешней БД).
const seen = new Set(($getWorkflowStaticData('global').seen_urls) || []);
const URL_RE = /https?:\/\/[^\s<>"')\]]+/gi;
const srcChat = $env.TG_SOURCE_CHAT_ID || '';
const out = [];
for (const item of $input.all()) {
  const msg = item.json.message || item.json;
  const text = msg.text || msg.caption || '';
  const chatId = msg.chat && msg.chat.id != null ? String(msg.chat.id) : '';
  // Ограничение источника: если TG_SOURCE_CHAT_ID задан — берём только этот чат.
  if (srcChat && chatId !== String(srcChat)) continue;
  for (let u of (text.match(URL_RE) || [])) {
    u = u.replace(/[.,;:!?]+$/, '');
    if (seen.has(u)) continue;
    seen.add(u);
    out.push({ json: { url: u, chat_id: chatId } });
  }
}
// Нет ссылок / всё уже видели -> пустой массив = пропуск сообщения.
return out;

// Срезаем script/style/комментарии и теги, нормализуем пробелы, ограничиваем 4000 символов.
const j = $input.item.json;
let html = '';
if (typeof j.data === 'string') html = j.data;
else if (typeof j.body === 'string') html = j.body;
else if (j.error || j.message) html = '';
else html = JSON.stringify(j);
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 4000);
let url = '';
try { url = $('Извлечь ссылки').item.json.url || ''; } catch (e) { url = ''; }
return { json: { url, text } };

