// Разбираем строгий JSON от AI; при битом ответе — безопасный fallback.
const j = $input.item.json;
let pageText = '', url = '';
try { pageText = $('HTML→текст').item.json.text || ''; } catch (e) { pageText = ''; }
try { url = $('Извлечь ссылки').item.json.url || ''; } catch (e) { url = ''; }
let content = '';
try { content = j.choices[0].message.content || ''; } catch (e) { content = ''; }
let parsed = null;
try {
  parsed = JSON.parse(String(content).replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) { parsed = null; }
const title = parsed && parsed.title ? String(parsed.title) : '(без заголовка)';
const summary = parsed && parsed.summary ? String(parsed.summary) : pageText.slice(0, 200);
const tags = parsed && Array.isArray(parsed.tags) ? parsed.tags.slice(0, 5).map(String) : [];
return { json: { url, title, summary, tags, ai_ok: !!parsed } };

// Формируем пост: заголовок, summary, теги-хэштеги, ссылка. Пробелы в теге -> подчёркивания.
const d = $input.item.json;
const tags = (Array.isArray(d.tags) ? d.tags : [])
  .map(t => '#' + String(t).replace(/^#+/, '').trim().replace(/\s+/g, '_'))
  .filter(t => t.length > 1);
const post = [d.title, '', d.summary, '', tags.join(' '), '', d.url].join('\n');
return { json: { post, url: d.url } };

// Публикация прошла -> запоминаем URL в static data (cap 1000, FIFO-вытеснение).
const staticData = $getWorkflowStaticData('global');
const CAP = 1000;
let seen = Array.isArray(staticData.seen_urls) ? staticData.seen_urls : [];
let url = '';
try { url = $('Собрать пост').item.json.url || ''; } catch (e) { url = ''; }
if (!url) { try { url = $('Извлечь ссылки').item.json.url || ''; } catch (e) { url = ''; } }
if (url && !seen.includes(url)) seen.push(url);
if (seen.length > CAP) seen = seen.slice(seen.length - CAP);
staticData.seen_urls = seen;
return { json: { url, remembered: seen.length } };
